1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Collection;
7	import java.util.Locale;
8	
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Household-identity rule for owners: two owners share a household when they have the
13	 * same last name and postcode. The householdId is derived deterministically from that
14	 * pair, so housemates share it automatically without any explicit link step.
15	 */
16	final class Households {
17	
18	    private Households() {
19	    }
20	
21	    /**
22	     * The deterministic household identifier: the first 12 hex characters of
23	     * SHA-256 over {@code normalizedLastName + '|' + postcode}.
24	     */
25	    static String idFor(Owner owner) {
26	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
27	        return sha256Hex12(normalize(owner.getLastName()) + "|" + postcode);
28	    }
29	
30	    /**
31	     * Whether {@code candidate} lands in an existing owner's household and so should be
32	     * rejected as a duplicate. A {@code sharesHousehold} flag of {@code true} opts out,
33	     * declaring the candidate a member of that household instead.
34	     */
35	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
36	        if (Boolean.TRUE.equals(sharesHousehold)) {
37	            return false;
38	        }
39	        return hasHousemate(existing, candidate);
40	    }
41	
42	    /** Household size for {@code candidate}: its existing housemates plus itself. */
43	    static int size(Collection<Owner> existing, Owner candidate) {
44	        long housemates = existing.stream().filter(other -> sameHousehold(other, candidate)).count();
45	        return (int) housemates + 1;
46	    }
47	
48	    /** Whether an existing owner already belongs to {@code candidate}'s household. */
49	    static boolean hasHousemate(Collection<Owner> existing, Owner candidate) {
50	        return existing.stream().anyMatch(other -> sameHousehold(other, candidate));
51	    }
52	
53	    private static boolean sameHousehold(Owner a, Owner b) {
54	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
55	    }
56	
57	    private static String normalize(String value) {
58	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
59	    }
60	
61	    private static String sha256Hex12(String key) {
62	        try {
63	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
64	            StringBuilder hex = new StringBuilder(24);
65	            for (int i = 0; i < 6; i++) {
66	                hex.append(String.format("%02x", digest[i]));
67	            }
68	            return hex.toString();
69	        }
70	        catch (NoSuchAlgorithmException e) {
71	            throw new IllegalStateException(e);
72	        }
73	    }
74	}
