3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Per-city sequence rule for owner customer codes: how many existing owners
9	 * already live in a candidate's city, compared case-insensitively.
10	 */
11	final class CityCodes {
12	
13	    private CityCodes() {
14	    }
15	
16	    /** How many existing owners share {@code candidate}'s city. */
17	    static int countInCity(Collection<Owner> existing, Owner candidate) {
18	        return (int) existing.stream().filter(other -> sameCity(other, candidate)).count();
19	    }
20	
21	    private static boolean sameCity(Owner a, Owner b) {
22	        return a.getCity() != null && a.getCity().equalsIgnoreCase(b.getCity());
23	    }
24	}
