1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Namesake rule for owners: two owners are namesakes when they share the same
9	 * first name and last name, compared case-insensitively.
10	 */
11	final class Namesakes {
12	
13	    private Namesakes() {
14	    }
15	
16	    /** How many existing owners are namesakes of {@code candidate}. */
17	    static int count(Collection<Owner> existing, Owner candidate) {
18	        return (int) existing.stream().filter(other -> sameName(other, candidate)).count();
19	    }
20	
21	    private static boolean sameName(Owner a, Owner b) {
22	        return equalsIgnoreCase(a.getFirstName(), b.getFirstName())
23	            && equalsIgnoreCase(a.getLastName(), b.getLastName());
24	    }
25	
26	    private static boolean equalsIgnoreCase(String a, String b) {
27	        return a != null && a.equalsIgnoreCase(b);
28	    }
29	}
