3	/**
4	 * Derives an owner's membership points and the level mapped from them. Points:
5	 * +2 for a present email, +1 when namesakeCount is 0, +2 for a household of 3 or
6	 * more and +3 for tenure over 365 days. Level maps points 0-1 to 1, 2-3 to 2,
7	 * 4-5 to 3 and 6 or more to 4.
8	 */
9	public final class MembershipLevels {
10	
11	    private MembershipLevels() {
12	    }
13	
14	    /** Membership points earned by {@code owner}. */
15	    public static int pointsOf(Owner owner) {
16	        int points = 0;
17	        if (owner.getEmail() != null) {
18	            points += 2;
19	        }
20	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
21	            points += 1;
22	        }
23	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
24	            points += 2;
25	        }
26	        java.time.LocalDate registered = owner.getRegistrationDate();
27	        if (registered != null
28	                && java.time.temporal.ChronoUnit.DAYS.between(registered, java.time.LocalDate.now()) > 365) {
29	            points += 3;
30	        }
31	        return points;
32	    }
33	
34	    /** Membership level (1 to 4) mapped from {@code owner}'s points. */
35	    public static int levelOf(Owner owner) {
36	        return levelOfPoints(pointsOf(owner));
37	    }
38	
39	    /** Maps a points total to its level band. */
40	    public static int levelOfPoints(int points) {
41	        if (points <= 1) {
42	            return 1;
43	        }
44	        if (points <= 3) {
45	            return 2;
46	        }
47	        if (points <= 5) {
48	            return 3;
49	        }
50	        return 4;
51	    }
